fn diagflat(v: Vec<f32>) -> Vec<Vec<f32>> {
    let n = v.len();
    let mut matrix = Vec::with_capacity(n);

    for i in 0..n {
        // Create each row using the create_row function
        let row = create_row(&v, i);
        matrix.push(row);
    }

    matrix
}

fn create_row(v: &Vec<f32>, i: usize) -> Vec<f32> {
    let n = v.len();
    let mut row = vec![0.0; n]; // Initialize a row with zeros
    row[i] = v[i]; // Set the diagonal element
    row
}

// Example usage
fn main() {
    let input = vec![1.0, 2.0, 3.0];
    let matrix = diagflat(input);
    
    for row in matrix {
        println!("{:?}", row);
    }
}